import functions.CoroutineManager_co_exit_to;

public class CoroutineSwitchDemo {

    public static void main(String[] args) {
        // Build the argument map that matches the expected structure:
        // { arg_object: <String>, thisCoroutine: <String>, toCoroutine: <String> }
        Map<String, String> callParams = new HashMap<>();
        callParams.put("arg_object", "resultData");   // the data you want to hand over
        callParams.put("thisCoroutine", "5");         // current coroutine ID
        callParams.put("toCoroutine", "10");          // target coroutine ID

        try {
            // Invoke the coroutine switch
            CoroutineManager_co_exit_to(callParams);
            System.out.println("Switched from coroutine 5 to coroutine 10 successfully.");
        } catch (Exception e) {
            // The function throws if the target coroutine is not available
            System.err.println("Failed to switch coroutines: " + e.getMessage());
        }
    }
}
```

